function positionMusicMenu(){
  const arrow=el("musicMenuBtn"), menu=el("musicChoiceMenu");
  if(!arrow||!menu)return;
  const r=arrow.getBoundingClientRect();
  const w=Math.min(360,Math.max(285,menu.offsetWidth||285));
  let left=r.right-w;
  left=Math.max(8,Math.min(left,window.innerWidth-w-8));
  let top=r.bottom+5;
  const h=menu.offsetHeight||230;
  if(top+h>window.innerHeight-8)top=Math.max(8,r.top-h-5);
  menu.style.left=left+"px";
  menu.style.top=top+"px";
}
function openMusicMenu(){
  const menu=el("musicChoiceMenu"), arrow=el("musicMenuBtn");
  if(!menu||!arrow)return;
  menu.classList.add("open");
  arrow.setAttribute("aria-expanded","true");
  requestAnimationFrame(positionMusicMenu);
}
function closeMusicMenu(){
  const menu=el("musicChoiceMenu"), arrow=el("musicMenuBtn");
  if(menu)menu.classList.remove("open");
  if(arrow)arrow.setAttribute("aria-expanded","false");
}
function toggleMusicMenu(ev){
  if(ev)ev.stopPropagation();
  const menu=el("musicChoiceMenu");
  if(menu&&menu.classList.contains("open"))closeMusicMenu(); else openMusicMenu();
