function updateMusicUI(){
  const main=el("musicBtn");
  const menu=el("musicChoiceMenu");
  if(main){
    main.textContent=musicEnabled?"♫ Musique ON":"♫ Musique OFF";
    const t=MUSIC_TRACKS[currentMusicIndex];
    main.title=(musicEnabled?"Couper":"Activer")+" — "+t.name+" — "+t.artist;
  }
  if(menu){
    menu.querySelectorAll("[data-music-index]").forEach(b=>{
      b.classList.toggle("active",Number(b.dataset.musicIndex)===currentMusicIndex);
    });
  }
}

